/* Region III province retail prices (₱/kg) -- feeds both the
   choropleth map and the leaderboard on Market Overview. Values match
   the reference screenshot (Aurora 220.00 +5.2% ... Pampanga 190.00 -2.0%);
   Nueva Ecija/Tarlac are filled in at plausible in-between levels since
   the reference leaderboard only lists its top five rows. */
export const MO_PROVINCES = [
  { name: "Aurora", price: 220.0, mom: 5.2 },
  { name: "Zambales", price: 210.5, mom: 3.1 },
  { name: "Bataan", price: 205.0, mom: 0.5 },
  { name: "Nueva Ecija", price: 198.0, mom: -0.3 },
  { name: "Bulacan", price: 195.25, mom: -1.2 },
  { name: "Pampanga", price: 190.0, mom: -2.0 },
  { name: "Tarlac", price: 182.0, mom: -2.6 }
];

export const MO_LEADERBOARD = MO_PROVINCES.slice(0, 5);

export const PRICE_DOMAIN = [170, 230];

/* GeoJSON source: faeldon/philippines-json-maps (province-level
   boundaries), mirrored through the jsdelivr GitHub CDN so no npm
   install is required. The exact PSGC region-code padding used in
   that repo's filenames couldn't be double-checked from inside this
   session, so two likely candidates are tried in order; if both miss,
   the map falls back to a labeled schematic so the page never breaks.
   If neither loads for you, open the repo, confirm the real filename
   under 2023/geojson/provdists/lowres/, and swap CANDIDATE_GEOJSON_URLS. */
export const CANDIDATE_GEOJSON_URLS = [
  "https://cdn.jsdelivr.net/gh/faeldon/philippines-json-maps@master/2023/geojson/provdists/lowres/provdists-region-030000000.0.001.json",
  "https://cdn.jsdelivr.net/gh/faeldon/philippines-json-maps@master/2023/geojson/provdists/lowres/provdists-region-300000000.0.001.json"
];

export const PROPERTY_NAME_KEYS = [
